def compute(vars):
    finished_goods_2018 = vars["v1"]
    finished_goods_2019 = vars["v2"]
    change = finished_goods_2019 - finished_goods_2018

    return {
        "value": change,
        "trace": {
            "finished_goods_2018": finished_goods_2018,
            "finished_goods_2019": finished_goods_2019,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
